const items = $input.all();
const result = [];

for (const item of items) {
  const fones = item.json.data?.[0]?.fones ?? [];

  const whatsappNumber = fones.find(f => f.whatsapp === true)?.numero ?? null;

  const { fones: _, ...clienteSemFones } = item.json.data[0];

  result.push({
    json: {
      ...clienteSemFones,
      whatsapp: whatsappNumber
    }
  });
}

return result;

