const binaryKey = 'data';
const binary = $input.item.binary[binaryKey];

// Lê o buffer do filesystem e converte pra base64
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64 = buffer.toString('base64');

return {
  json: {
    base64: base64,
    mimeType: binary.mimeType,
    dataUri: `data:${binary.mimeType};base64,${base64}`,
    fileSize: binary.fileSize,
    fileName: binary.fileName
  }
};

